	NocatFarm.Core.DlcAchievements.Map two = new() { App = 1, Names = ["both", "base"], Groups = [new() { App = 10, Ids = [10] }, new() { App = 20, Ids = [20] }], Owners = new() { ["both"] = [10, 20] } };
	Check("dlc rule: claimed by two DLC - needs both",
